package main

import "fmt"

func swap(a int, b int) {
  var temp int
  temp = a
  a = b
  b = temp
}

func main() {
  var a int = 10
  var b int = 20

  // swap

  fmt.Println("a =", a, " b =", b)
}

```

以上，只是值传递，并不会改变main函数中的a,b变量

```go
package main

import "fmt"

func swap(a *int, b *int) {
  var temp int
  temp = *a // 把a的内存地址赋值给temp
  *a = *b // 把b的内存地址赋值给a的内存地址
  *b = temp // 把temp的值赋值给b的内存地址
}

func main() {
  var a int = 10
  var b int = 20

  swap(&a, &b)

  fmt.Println("a =", a, " b =", b)
}

```

