func main() {
	var a int = 10

  var aa *int // 一级指针
	aa = &a
	fmt.Println(&a, " ", aa)

	var aaa **int // 二级指针
	aaa = &aa

	fmt.Println(&aa, " ", aaa)

	**aaa = 22

