import "fmt"

func main() {
	s := []int{2,4,1,23,5,6,223,1231}

	s1 := s[:2]
	fmt.Println(s1)
	s1[0] = 123 // 改变s1的第0位值，s也会改变
	fmt.Println(s1)
	fmt.Println(s)
}

```

使用copy 可以将底层数组的slice一起进行拷贝

```go
