func main() {
	s := []int{1,2,3}

	s1 := make([]int, 3)

	// 将s中的值，一次拷贝到s1中
	copy(s1, s)
	s1[0] = 123

	fmt.Println(s1) // [123 2 3]
	fmt.Println(s) // [1 2 3]
}

