另有一种实例化的写法，这样就不用嵌套父类的实例化，更加的直观

```go
var s SuperMan
s.name = "李4"
s.sex = "男"
s.level = 18

```

以下是完整例子

```go
package main

import "fmt"

type Human struct {
	name string
	sex string
}

func (this *Human) Eat() {
	fmt.Println("Human.Eat()...", this)
}

func (this *Human) Walk() {
	fmt.Println("Human.Walk()...")
}

type SuperMan struct {
	// SuperMan类继承了Human类的方法
	Human

	level int
}

// 重定义父类的 Eat() 方法
func (this *SuperMan) Eat() {
	fmt.Println("SuperMan.Eat()...", this)
}

// SuperMan类中的新方法
func (this *SuperMan) Fly() {
	fmt.Println("SuperMan.Fly()...")
}

func main() {
	h := Human{name: "张三", sex: "女"}
	// h := Human{"张三", "女"} // 简写，需要按照顺序

	h.Eat()
	h.Walk()

	s := SuperMan{Human{"李4", "男"}, 18}

	s.Eat()
  s.Walk() // 因为Walk()方法，没有重写，所以调用的是父类的Walk()方法
	s.Fly()
}
/*
Human.Eat()... &{张三 女}
Human.Walk()...
SuperMan.Eat()... &{{李4 男} 18}
Human.Walk()...
SuperMan.Fly()...
*/

```

## 多态

### 接口的定义

```go
// 本质是一个指针
type AnimalIF interface {
	Sleep()
	GetColor() string // 获取动物的颜色
	GetType() string // 获取动物的种类
}

```

### 多态

一个类实现一个接口，必须将接口中的方法都实现

Golang 中，类实现了接口中的所有方法，就实现了这个接口。

```go
package main

import "fmt"

// 本质是一个指针
type AnimalIF interface {
	Sleep()
	GetColor() string // 获取动物的颜色
	GetType() string // 获取动物的种类
}

// 具体的类
type Cat struct {
	color string // 猫的颜色
}
// 实现接口中的方法
func (this *Cat) Sleep() {
	fmt.Println("Cat.Sleep()...")
}
func (this *Cat) GetColor() string {
	fmt.Println("Cat.GetColor()...")
	return this.color
}
func (this *Cat) GetType() string {
	fmt.Println("Cat.GetType()...")
	return "Cat"
}

// 具体的类
type Dog struct {
	color string
}
// 实现接口中的方法
func (this *Dog) Sleep() {
	fmt.Println("Dog.Sleep()...")
}
func (this *Dog) GetColor() string {
	fmt.Println("Dog.GetColor()...")
	return this.color
}
func (this *Dog) GetType() string {
	fmt.Println("Dog.GetType()...")
	return "Dog"
}

func showAnimal(animal AnimalIF) {
	animal.Sleep() // 多态
	fmt.Println("color =", animal.GetColor())
	fmt.Println("kind =", animal.GetType())
}

func main() {
	var animal AnimalIF // 父类型引用指向子类型对象
	animal = &Dog{"红色"} // 多态
	animal.Sleep()

	animal = &Cat{"黑色"} // 多态
	animal.Sleep()

	cat := Cat{"绿色"}
	dog := Dog{"白色"}
	showAnimal(&cat)
	showAnimal(&dog)
}

```

以上就通过接口，实现了go语言中的多态。父类型引用指向子类型对象。

这些都和Java中的多态机制的概念和作用基本保持一致，只是实现方式有了区别。

### interface 空接口通用万能类型

空接口：`interface{}`

int、string、float32、float64、struct... 都实现了 `interface{}`，根据多态机制，`interface{}` 类型 引用 任意的数据类型。（这就类似于Java中的 Object 对象）

```go
package main

import "fmt"

// interface{} 是万能数据类型
func myFunc(arg interface{}) {
	fmt.Println("myFunc is called...")
	fmt.Println(arg)

	// interface{} 提供 “类型断言” 机制
	value, ok := arg.(string)
	if !ok {
		fmt.Println("arg is not string type")
		fmt.Println("============\n")
	} else {
		fmt.Println("arg is string type, value =", value)
		fmt.Printf("arg type is %T\n", arg)
		fmt.Printf("value type is %T\n", value)
		fmt.Println("============\n")
	}
}

type Book struct {
	auth string
}

func main() {
	book := Book{"Golang"}
	myFunc(book)
	myFunc(100)
	myFunc(3.14)
	myFunc("gantoho")
}

```

