案例：产生5个不同的随机数放进数组中

```java
package org.example;

import java.util.Random;

public class Main {
    public static void main(String[] args) throws Exception {
        int[] arr = new int[5];

        Random random = new Random();
        int num;

        int count = 0;


        while (count < 5) {
            num = random.nextInt(5);
            int count1 = 0;
            if(count == 0) {
                arr[count] = num;
                count++;
            }
            for (int i = 0; i < count; i++) {
                if(num == arr[i]) {
                    count1++;
                }
            }
            if(count1 == 0) {
                arr[count] = num;
                count++;
            }
        }
        for (int i = 0; i < arr.length; i++) {
            System.out.println(arr[i]);
        }
    }
}

```

