            fos.write(bytes);
            // 将byte数组部分写出
            fos.write(bytes, 0, 2); // 再写出97/a 98/b
            // 写完之后,最好一定要刷新
            fos.flush();
        } catch (FileNotFoundException e) {
            throw new RuntimeException(e);
        } catch (IOException e) {
            throw new RuntimeException(e);
        } finally {
            if(fos != null) {
                try {
                    fos.close();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }
    }
